import numpy as np
components = {
'A': np.array([[6,6],[6,6]]),
'C': np.array([[1,4],[2,4],[4,4],[4,4],[4,4],[4,4]]),
'F': np.array([[3,4],[3,4],[3,3],[3,3]]),
'B': np.array([[9,9],[9,9]]),
'D': np.array([[6,6],[6,6]]),
'E': np.array([[6,7],[7,6],[7,7],[7,7],[7,7],[7,7]]),
}
# Rotate portrait components counterclockwise, center in max width 6, stack
out=[]
for name in ['A','C','F','B','D','E']:
    a=components[name]
    if a.shape[0] > a.shape[1]:
        a=np.rot90(a,1)
    pad=(6-a.shape[1])//2
    for row in a:
        out.append([8]*pad+row.tolist()+[8]*(6-a.shape[1]-pad))
print(np.array(out).shape)
for row in out: print(*row)
